-- Généré par tests/build_guide.lua depuis GUIDE.esES.md : ne pas éditer à la main.
local _, NS = ...
NS.guides = NS.guides or {}
NS.guides.esES = {
    { "h1", "Guía de Panorama" },
    { "p", "Cómo usar Panorama en WoW Forever y cómo configurar HDR en Windows." },
    { "p", "|cffffd100Primero, haz una copia de tus ajustes.|r Panorama cambia ajustes del juego, y quitar el addon no los devuelve a su estado anterior. Antes de cambiar nada, cierra el juego y copia la carpeta |cffffd100WTF|r de tu instalación del juego en un lugar seguro. Para volver atrás, cierra el juego y vuelve a poner esa copia en su sitio." },
    { "h2", "1. Abrir la ventana" },
    { "li", "Escribe |cffffd100/pano|r o haz clic izquierdo en el botón de Panorama del minimapa.", "-" },
    { "li", "En Opciones > AddOns > Panorama también hay un botón que la abre.", "-" },
    { "li", "Arrastra la barra de título para mover la ventana. Escape o el botón de cierre la cierra.", "-" },
    { "p", "El botón del minimapa:" },
    { "li", "El clic izquierdo abre o cierra la ventana.", "-" },
    { "li", "El clic derecho muestra los preajustes, deshacer, rehacer y el reinicio de los gráficos.", "-" },
    { "li", "Arrástralo para moverlo alrededor del minimapa. |cffffd100/pano minimap|r lo muestra u oculta.", "-" },
    { "h2", "2. La ventana" },
    { "row", "|cffffd100Simple|r, |cffffd100Avanzado|r (junto al título)", "Simple: cada pestaña muestra una lista corta de los ajustes principales, sin secciones. Avanzado: todos los ajustes, por secciones, con las reglas por lugar y la sección Expertos. En la primera instalación es Simple; si ya usabas Panorama, es Avanzado. La búsqueda siempre encuentra todos los ajustes." },
    { "row", "Guía (arriba a la derecha)", "Abre esta guía en el juego." },
    { "row", "Menú |cffffd100Opciones|r (arriba a la derecha)", "|cffffd100Idioma|r (idioma del juego o uno de diez idiomas; al cambiarlo se recarga la interfaz), |cffffd100Aplicar en cada conexión|r, |cffffd100Botón del minimapa|r, |cffffd100Restablecer todo…|r." },
    { "row", "|cffffd100Aspecto actual:|r (barra bajo el título)", "El aspecto que hay ahora sobre el mundo y quién lo fija: tú, Día y noche o el lugar. Su botón (|cffffd100Editar|r, |cffffd100Editar esta regla|r) abre dónde cambiarlo. Pasa el ratón por la barra para ver cuál va primero." },
    { "row", "Pestañas", "|cffffd100Imagen|r (calidad gráfica), |cffffd100HDR|r, |cffffd100Ambiente|r (aspecto del mundo), |cffffd100Mis filtros|r. Se recuerda la pestaña abierta." },
    { "row", "Cuadro de búsqueda (a la derecha de las pestañas)", "Escribe una palabra para listar los ajustes que coinciden de todas las pestañas. Bórrala para volver." },
    { "row", "Preajustes (pestaña Imagen)", "Bajo, Medio, Alto, Extra. Se resalta el preajuste que coincide con tus ajustes." },
    { "row", "Pie", "|cffffd100Deshacer|r anula tu último cambio: control deslizante, casilla, preajuste, filtro, ambiente o Restablecer todo. |cffffd100Rehacer|r lo recupera. Los últimos 20 cambios se conservan hasta |cffffd100/reload|r. |cffffd100Reiniciar|r reinicia el motor gráfico." },
    { "p", "En el modo Avanzado, haz clic en el título de una sección para plegarla o desplegarla. La sección |cffffd100Expertos (solo consola)|r empieza plegada. El título de una sección indica cuántos de sus ajustes has cambiado." },
    { "h3", "Una línea de ajuste" },
    { "li", "|cffffd100Control deslizante|r: el valor se escribe al soltar el botón del ratón, no mientras arrastras.", "-" },
    { "li", "|cffffd100Cuadro de valor|r junto al control deslizante: escribe un valor y pulsa Intro o haz clic en otro sitio. Escape cancela, Tab pasa al cuadro siguiente. La coma sirve como separador decimal. El valor se mantiene dentro del rango del control deslizante.", "-" },
    { "li", "|cffffd100Botón Predeterminado|r: devuelve ese ajuste a su valor predeterminado. Pasa el ratón por encima para ver el valor.", "-" },
    { "li", "|cffffd100Marca dorada|r a la izquierda: has cambiado este ajuste.", "-" },
    { "li", "|cffffd100Menú del juego|r: cuando un menú del juego también establece este valor, la ayuda de la etiqueta lo nombra. Ese menú no vuelve a leer el valor, así que puede mostrar otro nivel.", "-" },
    { "li", "|cffffd100Línea en gris|r: depende de otro ajuste que está desactivado (por ejemplo, |cffffd100Calidad de la niebla volumétrica|r sin |cffffd100Niebla volumétrica|r, la intensidad del tono sin un tono), o un modo la fija. Pasa el ratón por la etiqueta para ver el motivo. Una línea que depende de otra aparece desplazada a la derecha, justo debajo de ella.", "-" },
    { "li", "Pasa el ratón por una etiqueta para leer su ayuda completa.", "-" },
    { "h2", "3. Preajustes" },
    { "row", "Bajo", "Máximo rendimiento. Poca distancia de visión, sin sombras." },
    { "row", "Medio", "Equilibrado. Buen rendimiento y sombras correctas." },
    { "row", "Alto", "Nivel Alto del juego. Sombras completas, todos los efectos." },
    { "row", "Extra", "Alto, con la mayor distancia de visión." },
    { "p", "Los preajustes solo cambian los ajustes de calidad gráfica de la pestaña Imagen. No tocan la cámara, el ratón, la interfaz, el enfoque, la baja latencia, HDR ni los filtros." },
    { "p", "¿Has cambiado de opinión? |cffffd100Deshacer|r (pie, o |cffffd100/pano undo|r) restaura los ajustes de antes del preajuste." },
    { "h2", "4. Ambiente" },
    { "p", "La pestaña Ambiente define el aspecto del mundo: efectos sobre la imagen. No cambian ningún ajuste del juego." },
    { "li", "|cffffd100Modo|r (parte superior de la pestaña): |cffffd100Fijo|r (el mismo filtro en todas partes), |cffffd100Día y noche|r (un tono diurno y un tono nocturno) o |cffffd100Según el lugar|r (ver más abajo). Fijo por defecto.", "-" },
    { "li", "|cffffd100Aquí|r: el lugar y la hora del día detectados ahora. Cuando una mazmorra, un interior o el clima pasan antes que una zona que has ajustado, lo indica.", "-" },
    { "li", "|cffffd100Filtro|r (modos Fijo y Día y noche): |cffffd100Base|r usa las líneas de abajo. Uno de tus filtros (pestaña Mis filtros) sustituye el tono, la viñeta y el grano, y aporta su contraste, su brillo y su gamma. |cffffd100Editar filtro|r lo abre en la pestaña Mis filtros.", "-" },
    { "li", "|cffffd100Tono|r: haz clic en una miniatura para aplicarlo al instante (Sepia, Cálido, Frío, Noche, Esmeralda, Crepúsculo). |cffffd100Intensidad del tono|r define su fuerza.", "-" },
    { "li", "|cffffd100Viñeta|r: oscurece los bordes de la pantalla.", "-" },
    { "li", "|cffffd100Grano|r: grano animado.", "-" },
    { "li", "|cffffd100Tono diurno|r y |cffffd100Tono nocturno|r (modo Día y noche): Panorama aplica el tono diurno de día y el tono nocturno de noche, según el día y la noche del juego. Sustituyen al tono. El cambio es gradual de 19:00 a 21:00 y de 5:00 a 7:00 (hora del servidor). Uno de tus filtros elegido en la línea Filtro los sustituye.", "-" },
    { "li", "|cffffd100Cielo|r: los mismos colores en degradado, completos arriba de la pantalla y más claros abajo. |cffffd100Intensidad del cielo|r define su fuerza.", "-" },
    { "li", "|cffffd100Barras negras|r: barras superior e inferior, de 0 a 20 % de la pantalla cada una, en todos los modos. El juego sigue renderizando lo que ocultan, así que no aumentan la tasa de fotogramas.", "-" },
    { "p", "En el modo Simple, la pestaña muestra el modo, el lugar, el filtro, el tono y su intensidad, y los tonos diurno y nocturno. La viñeta, el grano, el cielo y las barras negras están en el modo Avanzado." },
    { "h3", "Según el lugar" },
    { "p", "En el modo |cffffd100Según el lugar|r, el tinte, el cielo, la viñeta y el grano cambian solos según dónde estés." },
    { "li", "Las líneas del modo Fijo se ocultan: la regla del lugar las sustituye. Solo quedan las barras negras. Sus valores siguen guardados y vuelven al cambiar de modo. En el modo Simple se aplican las reglas incluidas; elige Avanzado para editarlas.", "-" },
    { "li", "|cffffd100Lugar|r: define el tinte, la viñeta y el grano. Orden: mazmorra o banda, interior, clima (lluvia, nieve, tormenta de arena) y luego el tipo de zona: tierras templadas, desiertos y tierras áridas, tierras nevadas, jungla y pantano, tierras corruptas, tierras volcánicas, bosques arcanos. Una zona aún desconocida cuenta como templada. El clima solo cuenta si la Intensidad del clima es superior a 0.", "-" },
    { "li", "|cffffd100Hora del día|r: define el cielo (día, amanecer y atardecer, noche). La noche sigue el día y la noche del juego; el amanecer y el atardecer, la hora del servidor. Sin cielo en interiores ni en mazmorras.", "-" },
    { "li", "|cffffd100Regla|r (modo Avanzado): elige una regla y ajústala debajo. El botón Predeterminado devuelve el valor incluido para esa regla. La primera vez que se abre la ventana, se abre la regla del lugar en el que estás. El menú tiene cinco grupos: |cffffd100Zonas|r (la zona en la que estás y las que has ajustado), |cffffd100Mazmorra e interior|r, |cffffd100Clima|r, |cffffd100Tipo de zona|r y |cffffd100Cielo (hora)|r. Los cuatro primeros ajustan el tinte, la viñeta, el grano y un preajuste gráfico: solo se aplica un lugar a la vez, en el orden indicado arriba. El último ajusta el cielo. No hace falta ajustar nada para empezar: cada regla ya tiene sus valores.", "-" },
    { "li", "|cffffd100Esta zona|r: primera opción del mismo menú, con el nombre de la zona en la que estás. Elígela para dar a esta zona su propio tinte, viñeta y grano, partiendo de su tipo de zona. Pasa entonces antes del tipo de zona, pero después de mazmorra, interior y clima. Las zonas que ajustas siguen en el menú. |cffffd100Volver al tipo de zona|r (junto al menú) elimina los valores de la zona: vuelve a seguir su tipo de zona.", "-" },
    { "li", "|cffffd100Todas las zonas|r: submenú del mismo menú, con todas las zonas conocidas. Elige una para ajustarla sin estar allí. Las zonas están ordenadas por continente.", "-" },
    { "li", "|cffffd100Preajuste|r y |cffffd100Distancia del escenario|r (sección |cffffd100Imagen|r de un lugar o de una zona): se aplican mientras estás en ese lugar, por encima de tus propios ajustes, sea cual sea el modo de ambiente. La distancia del escenario del lugar va antes que la del preajuste. Tus propios ajustes se conservan y vuelven cuando te vas. |cffffd100Mis ajustes|r no cambia nada. Ejemplo: Bajo en mazmorras, Extra en una zona que te gusta. En una mazmorra o banda, la primera opción del menú ajusta solo esa mazmorra. En la pestaña Imagen, |cffffd100Aquí: …|r aparece junto a los preajustes mientras un lugar aplica los suyos; en el modo Avanzado, abre esa regla. En combate, el cambio espera al final del combate.", "-" },
    { "li", "|cffffd100Filtro|r (primera línea de la sección |cffffd100Aspecto|r de un lugar o de una zona): ese lugar usa uno de tus filtros de la pestaña Mis filtros, con su contraste, su brillo y su gamma. |cffffd100Ajustes de abajo|r: el tinte, la viñeta y el grano de la regla. La sección Aspecto solo se aplica en el modo Según el lugar.", "-" },
    { "h2", "5. Mis filtros" },
    { "p", "La pestaña Mis filtros sirve para crear tantos filtros propios como quieras. El filtro abierto solo se muestra en el mundo en vista previa; el que se aplica se elige en la pestaña Ambiente. |cffffd100Nuevo|r añade uno y lo abre, |cffffd100Eliminar|r quita el filtro abierto: el filtro de la pestaña Ambiente y las reglas que lo usaban vuelven a no tener filtro. Siempre queda un filtro." },
    { "li", "|cffffd100Filtro|r: elige el filtro que ajustan las líneas de abajo. |cffffd100Nombre|r: ponle un nombre (Intro para confirmar).", "-" },
    { "li", "|cffffd100Tono|r: haz clic en una miniatura para dar ese color al filtro. |cffffd100Rojo|r, |cffffd100Verde|r, |cffffd100Azul|r (en %): su color exacto. |cffffd100Intensidad del tono|r: su fuerza.", "-" },
    { "li", "|cffffd100Viñeta|r y |cffffd100Grano|r: los del filtro.", "-" },
    { "li", "|cffffd100Contraste|r, |cffffd100Brillo|r, |cffffd100Gamma|r: ajustes de imagen que el filtro da al juego mientras está aplicado; después vuelven tus propios valores. Mis ajustes: no cambia nada. Según el modo de pantalla, pueden no tener efecto.", "-" },
    { "li", "En el modo Simple, la pestaña solo muestra el tono y la intensidad del tono.", "-" },
    { "li", "Mientras la pestaña está abierta, el filtro mostrado se ve en directo en el juego. La barra |cffffd100Aspecto actual:|r indica cuándo es solo una vista previa.", "-" },
    { "li", "Para usar un filtro: elígelo en la línea |cffffd100Filtro|r de la pestaña Ambiente (modos Fijo y Día y noche), o de un lugar o una zona (modo Según el lugar). Entonces sustituye el tono, la viñeta y el grano. |cffffd100Base|r o |cffffd100Ajustes de abajo|r: no cambia nada.", "-" },
    { "h2", "6. Tus valores y el juego" },
    { "li", "En la primera instalación, Panorama lee tus ajustes actuales del juego. No cambia nada hasta que muevas un control.", "-" },
    { "li", "Un cambio hecho en el menú de Gráficos del juego o con |cffffd100/console|r se muestra en la ventana.", "-" },
    { "li", "|cffffd100Aplicar en cada conexión|r (menú Opciones, activado por defecto): los ajustes que cambiaste en Panorama se escriben de nuevo en cada conexión. Los demás siguen el menú de Gráficos del juego.", "-" },
    { "li", "Un cambio hecho durante el combate se aplica cuando termina el combate.", "-" },
    { "li", "Algunos ajustes, como MSAA, necesitan reiniciar los gráficos. Haz clic en |cffffd100Reiniciar|r en el pie o escribe |cffffd100/pano restart|r. La pantalla parpadea un segundo.", "-" },
    { "h2", "7. HDR en Windows" },
    { "p", "Los ajustes de HDR existen en el juego solo como comandos de consola. Panorama los muestra en la pestaña |cffffd100HDR|r. Necesitas un monitor compatible con HDR." },
    { "h3", "Paso 1: activar HDR en Windows" },
    { "p", "Windows 11:" },
    { "li", "Abre |cffffd100Configuración > Sistema > Pantalla|r.", "1." },
    { "li", "Selecciona el monitor HDR si tienes más de uno.", "2." },
    { "li", "Activa |cffffd100Usar HDR|r. El atajo |cffffd100Win + Alt + B|r también lo activa o desactiva.", "3." },
    { "p", "Windows 10: |cffffd100Configuración > Sistema > Pantalla > Configuración de color HD de Windows|r (Windows HD Color settings), y luego activa |cffffd100Reproducir juegos y aplicaciones HDR|r (Play HDR games and apps)." },
    { "p", "Comprueba también que HDR esté activado en el menú propio del monitor, si tiene esa opción." },
    { "p", "Desactiva el |cffffd100HDR automático|r (Auto HDR) de Windows 11: |cffffd100Configuración > Sistema > Pantalla > HDR|r. Sirve para juegos sin HDR. WoW genera su propia imagen HDR." },
    { "h3", "Paso 2: encontrar el brillo máximo de tu monitor" },
    { "p", "Instala la aplicación gratuita |cffffd100Calibración de HDR de Windows|r (Windows HDR Calibration) desde la Microsoft Store y ejecútala. La luminancia máxima que encuentra es el brillo máximo de tu monitor, en nits." },
    { "p", "Sin la aplicación, usa la clasificación HDR del monitor: DisplayHDR 400 significa unos 400 nits, DisplayHDR 600 unos 600, DisplayHDR 1000 unos 1000." },
    { "h3", "Paso 3: configurar HDR en Panorama" },
    { "p", "Abre |cffffd100/pano|r, pestaña |cffffd100HDR|r. En el modo Simple, la pestaña solo muestra las tres primeras líneas de abajo: elige |cffffd100Avanzado|r para ver |cffffd100Intensidad HDR|r y el brillo de referencia." },
    { "li", "Marca |cffffd100Salida HDR|r.", "1." },
    { "li", "Marca |cffffd100Usar brillo máximo|r o |cffffd100Usar brillo de referencia|r: uno u otro, nunca los dos. Sin ninguno, la imagen se oscurece.", "2." },
    { "p", "|cffffd100Modo de brillo máximo (recomendado)|r" },
    { "li", "Marca |cffffd100Usar brillo máximo|r.", "-" },
    { "li", "Ajusta |cffffd100Brillo máximo (nits)|r al valor encontrado en el paso 2.", "-" },
    { "li", "|cffffd100Intensidad HDR|r solo funciona en este modo. El valor predeterminado del juego es 2. Cámbialo en pasos pequeños y compara: Blizzard no documenta su efecto exacto.", "-" },
    { "p", "|cffffd100Modo de brillo de referencia|r" },
    { "li", "Marca |cffffd100Usar brillo de referencia|r.", "-" },
    { "li", "|cffffd100Brillo de referencia (nits)|r es el brillo del blanco en la escena. 203 es el valor estándar. Súbelo si la imagen se ve demasiado oscura en una habitación luminosa. Intensidad HDR no tiene efecto en este modo.", "-" },
    { "p", "Si la imagen no cambia, haz clic en |cffffd100Reiniciar|r en el pie." },
    { "h3", "Solución de problemas de HDR" },
    { "row", "Imagen muy oscura", "Marca uno de los dos modos de brillo." },
    { "row", "Imagen gris o deslavada", "Activa HDR en Windows (paso 1) y en el menú del monitor." },
    { "row", "HDR automático activado en Windows", "Desactívalo (paso 1)." },
    { "row", "Luces demasiado brillantes o planas", "Ajusta el brillo máximo al valor real de tu monitor (paso 2)." },
    { "row", "Quieres desactivar HDR", "Desmarca |cffffd100Salida HDR|r." },
    { "p", "Cada línea de HDR tiene un botón Predeterminado que restaura el valor del juego." },
    { "h2", "8. Comandos" },
    { "row", "|cffffd100/pano|r", "Abrir o cerrar la ventana" },
    { "row", "|cffffd100/pano low|r, |cffffd100/pano medium|r, |cffffd100/pano high|r, |cffffd100/pano extra|r", "Aplicar un preajuste" },
    { "row", "|cffffd100/pano undo|r", "Deshacer el último cambio" },
    { "row", "|cffffd100/pano redo|r", "Rehacer el cambio que acabas de deshacer" },
    { "row", "|cffffd100/pano reset|r", "Devolver cada ajuste y cada filtro a su valor por defecto" },
    { "row", "|cffffd100/pano status|r", "Muestra en el chat el lugar y el momento detectados y los filtros aplicados ahora (durante un fundido, los valores de destino)" },
    { "row", "|cffffd100/pano apply|r", "Escribir de nuevo los ajustes cambiados en Panorama" },
    { "row", "|cffffd100/pano restart|r", "Reiniciar el motor gráfico" },
    { "row", "|cffffd100/pano minimap|r", "Mostrar u ocultar el botón del minimapa" },
    { "row", "|cffffd100/pano blackbars 10|r", "Bandas negras al 10 % de la altura de la pantalla (0 a 20). |cffffd100off|r las quita" },
    { "row", "|cffffd100/pano grain 10|r", "Grano a 10 (0 a 100). |cffffd100off|r lo quita" },
    { "row", "|cffffd100/pano vignette 10|r", "Viñeta a 10 (0 a 100). |cffffd100off|r la quita" },
    { "h2", "9. Restablecer" },
    { "li", "El botón |cffffd100Predeterminado|r de cada línea restablece ese ajuste.", "-" },
    { "li", "El botón |cffffd100Predeterminado|r del menú de Gráficos del juego restablece solo los ajustes que gestiona ese menú, y Panorama lo sigue. Usa los botones Predeterminado de |cffffd100/pano|r para los demás y para los filtros.", "-" },
    { "li", "|cffffd100Restablecer todo…|r (menú Opciones, con confirmación) o |cffffd100/pano reset|r: devuelve cada ajuste de la ventana, cambiado en Panorama o no, y cada filtro a su valor por defecto. |cffffd100Deshacer|r lo anula hasta |cffffd100/reload|r. La pestaña Ambiente y las zonas ajustadas también se restablecen. Tus filtros de la pestaña Mis filtros también se borran.", "-" },
}
NS.guides.esMX = NS.guides.esES
